using MagasinGestion.Data;
using Microsoft.Data.Sqlite;

namespace MagasinGestion.Services;

public sealed record CartLine(long ProductId, int Quantity);
public sealed record SaleQuote(decimal Total, decimal CashChange, IReadOnlyList<string> PriceChanges);
public sealed class SaleService(SqliteConnectionFactory factory)
{
    public SaleQuote Validate(long userId, IReadOnlyList<CartLine> cart, string paymentMode, decimal received, string attemptId)
    {
        if (cart.Count == 0) throw new InvalidOperationException("Le panier est vide.");
        if (cart.Any(x => x.Quantity <= 0)) throw new ArgumentException("Les quantités doivent être des entiers strictement positifs.");
        using var db=factory.Create(); using var tx=db.BeginTransaction(); decimal total=0; decimal change=0; var changes=new List<string>(); var rows=new List<(long id,string reference,string name,decimal price,decimal stock,int qty)>();
        foreach(var line in cart){using var p=db.CreateCommand();p.Transaction=tx;p.CommandText="SELECT Reference,Nom,PrixVente,Actif,COALESCE((SELECT SUM(Quantite) FROM MouvementStock WHERE ProduitId=Produit.Id),0) FROM Produit WHERE Id=$i";p.Parameters.AddWithValue("$i",line.ProductId);using var r=p.ExecuteReader();if(!r.Read())throw new InvalidOperationException("Produit introuvable.");var reference=r.GetString(0);var name=r.GetString(1);var price=r.GetDecimal(2);if(!r.GetBoolean(3))throw new InvalidOperationException($"Le produit {reference} est archivé.");var stock=r.GetDecimal(4);if(stock<line.Quantity)throw new InvalidOperationException($"Stock insuffisant pour {reference}.");rows.Add((line.ProductId,reference,name,price,stock,line.Quantity));total+=price*line.Quantity;}
        if(paymentMode=="Espèces"){if(received<total)throw new InvalidOperationException("Le montant reçu est insuffisant.");change=received-total;}else{received=total;}
        using var sale=db.CreateCommand();sale.Transaction=tx;sale.CommandText="INSERT INTO Vente(Numero,UtilisateurId,DateVente,Total,ModePaiement,MontantRecu,Monnaie,TentativeId) VALUES($n,$u,$d,$t,$m,$r,$c,$a);SELECT last_insert_rowid();";var number=$"V-{DateTime.Now:yyyyMMddHHmmss}-{Random.Shared.Next(1000,9999)}";sale.Parameters.AddWithValue("$n",number);sale.Parameters.AddWithValue("$u",userId);sale.Parameters.AddWithValue("$d",DateTime.UtcNow.ToString("O"));sale.Parameters.AddWithValue("$t",total);sale.Parameters.AddWithValue("$m",paymentMode);sale.Parameters.AddWithValue("$r",received);sale.Parameters.AddWithValue("$c",change);sale.Parameters.AddWithValue("$a",attemptId);var saleId=Convert.ToInt64(sale.ExecuteScalar());
        foreach(var x in rows){using var l=db.CreateCommand();l.Transaction=tx;l.CommandText="INSERT INTO LigneVente(VenteId,ProduitId,Quantite,PrixUnitaire,Total,ReferenceEnregistree,NomEnregistre) VALUES($v,$p,$q,$u,$t,$r,$n)";l.Parameters.AddWithValue("$v",saleId);l.Parameters.AddWithValue("$p",x.id);l.Parameters.AddWithValue("$q",x.qty);l.Parameters.AddWithValue("$u",x.price);l.Parameters.AddWithValue("$t",x.price*x.qty);l.Parameters.AddWithValue("$r",x.reference);l.Parameters.AddWithValue("$n",x.name);l.ExecuteNonQuery();using var m=db.CreateCommand();m.Transaction=tx;m.CommandText="INSERT INTO MouvementStock(ProduitId,UtilisateurId,Type,Quantite,StockAvant,StockApres,Motif,DateMouvement,Origine) VALUES($p,$u,'Vente',$q,$b,$a,$m,$d,'Vente')";m.Parameters.AddWithValue("$p",x.id);m.Parameters.AddWithValue("$u",userId);m.Parameters.AddWithValue("$q",-x.qty);m.Parameters.AddWithValue("$b",x.stock);m.Parameters.AddWithValue("$a",x.stock-x.qty);m.Parameters.AddWithValue("$m",number);m.Parameters.AddWithValue("$d",DateTime.UtcNow.ToString("O"));m.ExecuteNonQuery();}
        using var audit=db.CreateCommand();audit.Transaction=tx;audit.CommandText="INSERT INTO JournalAudit(UtilisateurId,Action,Entite,EntiteId,Details,DateAction) VALUES($u,'Vente','Vente',$i,$d,$t)";audit.Parameters.AddWithValue("$u",userId);audit.Parameters.AddWithValue("$i",saleId);audit.Parameters.AddWithValue("$d",number);audit.Parameters.AddWithValue("$t",DateTime.UtcNow.ToString("O"));audit.ExecuteNonQuery();tx.Commit();return new(total,change,changes);
    }
    public void Cancel(long saleId,long adminId,string reason){if(string.IsNullOrWhiteSpace(reason))throw new ArgumentException("Le motif est obligatoire.");using var db=factory.Create();using var tx=db.BeginTransaction();using var check=db.CreateCommand();check.Transaction=tx;check.CommandText="SELECT Annulee FROM Vente WHERE Id=$i";check.Parameters.AddWithValue("$i",saleId);if(Convert.ToInt32(check.ExecuteScalar()??-1)<0)throw new InvalidOperationException("Vente introuvable.");if(Convert.ToInt32(check.ExecuteScalar()??0)!=0)throw new InvalidOperationException("Cette vente est déjà annulée.");using var lines=db.CreateCommand();lines.Transaction=tx;lines.CommandText="SELECT ProduitId,Quantite,COALESCE((SELECT SUM(Quantite) FROM MouvementStock WHERE ProduitId=LigneVente.ProduitId),0) FROM LigneVente WHERE VenteId=$i";lines.Parameters.AddWithValue("$i",saleId);using var r=lines.ExecuteReader();var list=new List<(long,decimal,decimal)>();while(r.Read())list.Add((r.GetInt64(0),r.GetDecimal(1),r.GetDecimal(2)));foreach(var x in list){using var m=db.CreateCommand();m.Transaction=tx;m.CommandText="INSERT INTO MouvementStock(ProduitId,UtilisateurId,Type,Quantite,StockAvant,StockApres,Motif,DateMouvement,Origine) VALUES($p,$u,'Annulation vente',$q,$b,$a,$m,$d,'Annulation')";m.Parameters.AddWithValue("$p",x.Item1);m.Parameters.AddWithValue("$u",adminId);m.Parameters.AddWithValue("$q",x.Item2);m.Parameters.AddWithValue("$b",x.Item3);m.Parameters.AddWithValue("$a",x.Item3+x.Item2);m.Parameters.AddWithValue("$m",reason);m.Parameters.AddWithValue("$d",DateTime.UtcNow.ToString("O"));m.ExecuteNonQuery();}using var update=db.CreateCommand();update.Transaction=tx;update.CommandText="UPDATE Vente SET Annulee=1 WHERE Id=$i;INSERT INTO AnnulationVente(VenteId,UtilisateurId,Motif,DateAnnulation) VALUES($i,$u,$m,$d)";update.Parameters.AddWithValue("$i",saleId);update.Parameters.AddWithValue("$u",adminId);update.Parameters.AddWithValue("$m",reason);update.Parameters.AddWithValue("$d",DateTime.UtcNow.ToString("O"));update.ExecuteNonQuery();tx.Commit();}
}
